import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time
import re

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Validate key format (64 hex chars)
        if not re.match(r'^[a-f0-9]{64}$', api_key):
            return jsonify({'error': 'Invalid key format'}), 401
        db = get_db()
        row = db.execute('SELECT id, role FROM api_keys WHERE key_hash = ?',
                        (hashlib.sha256(api_key.encode()).hexdigest(),)).fetchone()
        if not row:
            return jsonify({'error': 'Unauthorized'}), 403
        request.user_id = row['id']
        request.user_role = row['role']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/search', methods=['GET'])
@require_api_key
def search_inventory():
    """Search inventory with flexible filtering.
    Supports: category, warehouse, min_qty, max_qty, sort_by, order
    """
    category = request.args.get('category', '')
    warehouse = request.args.get('warehouse', '')
    min_qty = request.args.get('min_qty', '0')
    sort_by = request.args.get('sort_by', 'name')
    order = request.args.get('order', 'ASC')

    # Build query with filters
    base_query = "SELECT id, name, sku, category, warehouse, quantity, updated_at FROM inventory WHERE 1=1"
    params = []

    if category:
        base_query += " AND category = ?"
        params.append(category)

    if warehouse:
        base_query += " AND warehouse = ?"
        params.append(warehouse)

    try:
        min_qty_val = int(min_qty)
        base_query += " AND quantity >= ?"
        params.append(min_qty_val)
    except ValueError:
        pass

    # Sort - whitelist column names but order direction is user-controlled
    allowed_columns = ['name', 'sku', 'category', 'warehouse', 'quantity', 'updated_at']
    if sort_by not in allowed_columns:
        sort_by = 'name'

    # ORDER BY with validated column but unvalidated direction
    base_query += f" ORDER BY {sort_by} {order}"

    base_query += " LIMIT 100"

    db = get_db()
    try:
        results = db.execute(base_query, params).fetchall()
        return jsonify({
            'results': [dict(row) for row in results],
            'count': len(results),
            'query_time': time.time()
        })
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Query failed'}), 500

@app.route('/api/v2/inventory/<int:item_id>', methods=['PUT'])
@require_api_key
def update_inventory(item_id):
    if request.user_role != 'admin':
        return jsonify({'error': 'Insufficient permissions'}), 403
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data provided'}), 400

    allowed_fields = ['name', 'category', 'warehouse', 'quantity']
    updates = []
    params = []
    for field in allowed_fields:
        if field in data:
            updates.append(f"{field} = ?")
            params.append(data[field])

    if not updates:
        return jsonify({'error': 'No valid fields'}), 400

    params.append(item_id)
    query = f"UPDATE inventory SET {', '.join(updates)}, updated_at = CURRENT_TIMESTAMP WHERE id = ?"
    db = get_db()
    db.execute(query, params)
    db.commit()
    return jsonify({'status': 'updated'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
